function Test-WsmJournal {
    param([string]$StateDirectory,[string]$PairId)
    $paths=Get-WsmOperationPaths $StateDirectory $PairId;$state=Read-WsmJson $paths.State;$hash='0'*64;$sequence=0
    $matched=($state.Sequence -eq 0 -and $state.JournalHash -ceq $hash)
    Read-WsmJournalEvents $paths | ForEach-Object {$row=$_.Row;if($row.Sequence -ne $sequence+1 -or $row.PreviousHash -cne $hash -or $row.PairId -cne $PairId -or $row.RunId -cne $state.RunId){throw 'Journal chain/sequence/identity mismatch; retain evidence.'};$sequence=$row.Sequence;$hash=$_.Hash;if($sequence -eq $state.Sequence){if($hash -cne $state.JournalHash){throw 'Checkpoint does not match its durable journal prefix.'};$matched=$true}}
    if(-not $matched){throw 'Checkpoint is absent from durable journal.'}
    [pscustomobject]@{JournalSequence=$sequence;JournalHash=$hash;StateSequence=$state.Sequence;StateHash=$state.JournalHash;Consistent=($sequence -eq $state.Sequence -and $hash -ceq $state.JournalHash);RecoveryRequired=($sequence -gt $state.Sequence);TamperResistance='Local administrator can rewrite journal and state; chain detects accidental corruption only'}
}
function Repair-WsmOperation {
    [CmdletBinding(SupportsShouldProcess)]param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[hashtable]$SidMap=@{})
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Manifest.Target.Fingerprint;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId
    Invoke-WsmLocked $paths.Root {$s=Get-WsmOperationState $paths $p -AllowRecovery;$journal=Test-WsmJournal $StateDirectory $s.PairId;if(-not $journal.Consistent){if(-not $PSCmdlet.ShouldProcess($s.PairId,'Replay verified durable journal to checkpoint')){return};Restore-WsmJournalCheckpoint $paths $s};if($s.Cutover -and $s.Cutover.NewTransactionsPossible -and -not (Test-WsmEvidence $s '' RollbackReconcile $ExpectedHash)){throw 'Post-activation recovery requires data reconciliation.'};$repaired=@()
        foreach($op in @($s.PendingOperations)){$item=@($p.Plan.Items | Where-Object ItemId -CEQ $op.ItemId)[0];if($op.Phase -eq 'RollbackAdapter'){if($op.ManifestHash -ine $ExpectedHash){throw 'Adapter rollback manifest mismatch.'};if($PSCmdlet.ShouldProcess($item.ItemId,'Finish durable reviewed adapter rollback')){Complete-WsmAdapterRollback $item $op $paths $s;$repaired+=$item.ItemId};continue};if($op.Phase -eq 'RollbackPrepared'){if($op.ManifestHash -ine $ExpectedHash -or $item.MigrationSpec.Adapter -ne 'FileScope'){throw 'Rollback recovery binding mismatch.'};if($PSCmdlet.ShouldProcess($item.ItemId,'Finish durable reviewed file rollback; retain displaced content')){Complete-WsmFileRollback $item $op $paths $s;$repaired+=$item.ItemId};continue};if($op.Phase -eq 'AdapterCreating'){if($op.ManifestHash -ine $ExpectedHash -or $op.Adapter -cne $item.MigrationSpec.Adapter -or -not $op.AbsentBefore){throw 'Adapter intent binding mismatch.'};if($op.Adapter -eq 'WindowsFeature'){if(-not $PSCmdlet.ShouldProcess($item.ItemId,'Reconcile and quarantine interrupted installer consumers')){continue};$baseline=Read-WsmInstallerBaseline $op $paths $op.ItemId;[void](Protect-WsmInstallerSideEffects $item.MigrationSpec.Desired $baseline)};$taskOwned=@();if($op.Adapter -ceq 'ScheduledTask'){if(@($op.FolderCreateIntents).Count){throw 'Task folder creation has a durable intent without receipt; reconcile owner-reviewed ownership before repair.'};$taskOwned=Get-WsmTaskSecurityReceiptsForSpec $item.MigrationSpec @($op.AuxiliaryOwnership)};$observed=Get-WsmAdapterState $item.MigrationSpec;if(-not $observed.Exists){if($op.Adapter -ceq 'ScheduledTask' -and $taskOwned.Count){throw 'Scheduled task is absent but owned folder receipts remain; keep ownership evidence and reconcile before repair.'};if($PSCmdlet.ShouldProcess($item.ItemId,'Abandon absent interrupted adapter build')){$s.PendingOperations=@($s.PendingOperations | Where-Object ItemId -CNE $op.ItemId);$s.Items=@($s.Items | Where-Object ItemId -CNE $op.ItemId);Add-WsmJournal $paths $s 'AdapterBuildAbandoned' $op.ItemId ([pscustomobject]@{Absent=$true})};continue};$check=Test-WsmAdapterConfiguration $item.MigrationSpec Staged $taskOwned;if(-not $check.Passed){throw 'Interrupted adapter exists but differs from exact staged spec/security; reconcile using retained intent before retry.'};if($PSCmdlet.ShouldProcess($item.ItemId,'Adopt verified staged adapter from durable absent-before intent')){$recoveredStatus='Succeeded';$bootBefore='';$installerSafety=$null;if($op.Adapter -eq 'WindowsFeature'){$baseline=Read-WsmInstallerBaseline $op $paths $op.ItemId;$installerSafety=Protect-WsmInstallerSideEffects $item.MigrationSpec.Desired $baseline;if(-not $op.PSObject.Properties['BootBefore'] -or -not $op.BootBefore){throw 'Interrupted feature install has no durable boot baseline; reconcile before adopting.'};$bootBefore=$op.BootBefore;if((Get-WsmBootStamp) -ceq $bootBefore){$recoveredStatus='RebootRequired'}};$record=[pscustomobject]@{InstallerBaselinePath=$(if($op.Adapter -eq 'WindowsFeature'){$op.InstallerBaselinePath}else{''});InstallerBaselineHash=$(if($op.Adapter -eq 'WindowsFeature'){$op.InstallerBaselineHash}else{''});InstallerSafety=$installerSafety;BootBefore=$bootBefore;ItemId=$op.ItemId;Status=$recoveredStatus;CreatedByTool=$true;AuxiliaryOwnership=$taskOwned;ActualHash=(Get-WsmHashText ($check.Actual | ConvertTo-Json -Depth 15 -Compress));Backup='';Target='';Error='';NativeCode=0};if($record.Status -eq 'RebootRequired'){$s.Stage='RebootRequired'};$s.Items=@($s.Items | Where-Object ItemId -CNE $op.ItemId)+@($record);$s.PendingOperations=@($s.PendingOperations | Where-Object ItemId -CNE $op.ItemId);Add-WsmJournal $paths $s 'AdapterRecovered' $op.ItemId $record;$repaired+=$op.ItemId};continue};if($op.ManifestHash -ine $ExpectedHash -or $item.MigrationSpec.Adapter -ne 'FileScope'){throw 'Pending operation plan mismatch.'};$target=ConvertTo-WsmCanonicalPath $item.MigrationSpec.TargetPath;$parent=[IO.Path]::GetDirectoryName($target);if($op.Target -ine $target -or [IO.Path]::GetDirectoryName($op.Staging) -ine $parent -or [IO.Path]::GetDirectoryName($op.Backup) -ine $parent -or [IO.Path]::GetFileName($op.Staging) -notlike '.wsm-stage-*' -or [IO.Path]::GetFileName($op.Backup) -notlike '.wsm-backup-*'){throw 'Recovery path escapes approved parent.'};foreach($path in @($target,$op.Staging,$op.Backup)){Assert-WsmNoReparse $path};$actual=Get-WsmFileScopeDigest $target $item.MigrationSpec.Metadata
            if($op.Phase -eq 'Prepared' -and $actual -ceq $op.ExpectedHash){if(-not $PSCmdlet.ShouldProcess($target,'Adopt verified completed scope switch')){continue}}
            elseif($op.Phase -eq 'Prepared' -and -not $actual -and (Test-Path -LiteralPath $op.Staging)){$check=Test-WsmFileScope $item $p $op.Staging $SidMap;if(-not $check.Passed -or $check.ActualHash -cne $op.ExpectedHash){throw 'Staging differs from prepared checkpoint.'};if(-not $PSCmdlet.ShouldProcess($target,'Finish interrupted approved scope switch')){continue};if([IO.Directory]::Exists($op.Staging)){[IO.Directory]::Move($op.Staging,$target)}else{[IO.File]::Move($op.Staging,$target)};$actual=$check.ActualHash}
            elseif($actual -ceq $op.PreviousHash){if(-not $PSCmdlet.ShouldProcess($target,'Abandon interrupted build; keep staging evidence and retry fresh')){continue};$s.PendingOperations=@($s.PendingOperations | Where-Object ItemId -CNE $op.ItemId);$s.Items=@($s.Items | Where-Object ItemId -CNE $op.ItemId);if($op.PSObject.Properties['PreviousRecord'] -and $op.PreviousRecord){$s.Items+=@($op.PreviousRecord)};Add-WsmJournal $paths $s 'BuildAbandoned' $op.ItemId ([pscustomobject]@{RetainedStaging=$op.Staging});continue}
            else{throw 'Target/staging do not match a safe checkpoint; manual reconciliation required.'}
            $record=[pscustomobject]@{ItemId=$op.ItemId;Status='Succeeded';CreatedByTool=$true;ActualHash=$actual;Backup=$op.Backup;Target=$target;Error='';NativeCode=0};if($record.Status -eq 'RebootRequired'){$s.Stage='RebootRequired'};$s.Items=@($s.Items | Where-Object ItemId -CNE $op.ItemId)+@($record);$s.PendingOperations=@($s.PendingOperations | Where-Object ItemId -CNE $op.ItemId);$repaired+=$op.ItemId;Add-WsmJournal $paths $s 'ScopeRecovered' $op.ItemId $record
        };[pscustomobject]@{Repaired=$repaired;Remaining=$s.PendingOperations.Count;State=$s}
    }
}
function Complete-WsmFileRollback($Item,$Operation,$Paths,$State) {
    $target=ConvertTo-WsmCanonicalPath $Item.MigrationSpec.TargetPath;$parent=[IO.Path]::GetDirectoryName($target)
    if($Operation.Target -ine $target -or [IO.Path]::GetDirectoryName($Operation.Retained) -ine $parent -or [IO.Path]::GetFileName($Operation.Retained) -notlike '.wsm-rollback-retained-*'){throw 'Rollback intent escapes approved target parent.'}
    if($Operation.Backup -and ([IO.Path]::GetDirectoryName($Operation.Backup) -ine $parent -or [IO.Path]::GetFileName($Operation.Backup) -notlike '.wsm-backup-*')){throw 'Rollback backup escapes approved target parent.'}
    foreach($path in @($target,$Operation.Retained,$Operation.Backup)){if($path){Assert-WsmNoReparse $path}}
    $metadata=$Item.MigrationSpec.Metadata;$current=Get-WsmFileScopeDigest $target $metadata;$retained=Get-WsmFileScopeDigest $Operation.Retained $metadata
    if($current -ceq $Operation.CurrentHash -and -not $retained){if([IO.Directory]::Exists($target)){[IO.Directory]::Move($target,$Operation.Retained)}else{[IO.File]::Move($target,$Operation.Retained)};$current='';$retained=$Operation.CurrentHash}
    if($retained -cne $Operation.CurrentHash){throw 'Displaced rollback target missing or drifting; preserve all roots and reconcile.'}
    if(-not $current -and $Operation.Backup){$backupHash=Get-WsmFileScopeDigest $Operation.Backup $metadata;if($backupHash -cne $Operation.BackupHash){throw 'Rollback backup drifted; restore blocked.'};if([IO.Directory]::Exists($Operation.Backup)){[IO.Directory]::Move($Operation.Backup,$target)}else{[IO.File]::Move($Operation.Backup,$target)};$current=Get-WsmFileScopeDigest $target $metadata}
    if($current -cne $Operation.BackupHash){throw 'Rollback target differs from approved previous root.'}
    $record=@($State.Items | Where-Object ItemId -CEQ $Item.ItemId)[0];$record.Status='RolledBack';$State.PendingOperations=@($State.PendingOperations | Where-Object ItemId -CNE $Item.ItemId)
    Add-WsmJournal $Paths $State RollbackCompleted $Item.ItemId ([pscustomobject]@{Status='RolledBack';Retained=$Operation.Retained})
}
function Complete-WsmAdapterRollback($Item,$Operation,$Paths,$State) {
    $spec=$Item.MigrationSpec;$record=@($State.Items | Where-Object ItemId -CEQ $Item.ItemId)
    if($record.Count -ne 1 -or -not $record[0].CreatedByTool -or $Operation.Adapter -cne $spec.Adapter -or $spec.Adapter -in @('FileScope','WindowsFeature','ManualWorkflow') -or $Operation.SpecHash -cne (Get-WsmHashText ($spec | ConvertTo-Json -Depth 40 -Compress))){throw 'Adapter rollback ownership/spec mismatch.'}
    $actual=Get-WsmAdapterState $spec
    $receipts=@();if($spec.Adapter -eq 'ScheduledTask'){$receipts=Get-WsmTaskSecurityReceiptsForSpec $spec (Get-WsmTaskSecurityOwnershipReceipts $State)}elseif($record[0].PSObject.Properties['AuxiliaryOwnership']){$receipts=@($record[0].AuxiliaryOwnership)}
    if($actual.Exists){$staged=Test-WsmAdapterConfiguration $spec Staged $receipts;$final=Test-WsmAdapterConfiguration $spec Final $receipts;if(-not $staged.Passed -and -not $final.Passed){throw 'Rollback object configuration drift; retain intent and reconcile before removing.'};Invoke-WsmAdapterActivation $spec $false;$staged=Test-WsmAdapterConfiguration $spec Staged $receipts;if(-not $staged.Passed){throw 'Rollback object did not reach verified disabled staging.'};Remove-WsmCreatedAdapter $spec;if((Get-WsmAdapterState $spec).Exists){throw 'Rollback adapter removal did not complete.'}}
    if($spec.Adapter -eq 'ScheduledTask' -and $receipts.Count){$beforeDelete={param($intent)$op=$Operation;if(-not $op.PSObject.Properties['FolderDeleteIntents']){$op | Add-Member NoteProperty FolderDeleteIntents @()};$op.FolderDeleteIntents+=@($intent);$detail=[pscustomobject]@{ItemId=$Item.ItemId;Adapter='ScheduledTask';ManifestHash=$Operation.ManifestHash;Phase='TaskFolderDeleteIntent';Intent=$intent;Receipt=$intent.Receipt};Add-WsmJournal $Paths $State 'TaskFolderDeleteIntent' $Item.ItemId $detail};$afterDelete={param($intent)$op=$Operation;$op.FolderDeleteIntents=@($op.FolderDeleteIntents | Where-Object OperationId -CNE $intent.OperationId);if(-not $op.PSObject.Properties['DeletedTaskFolders']){$op | Add-Member NoteProperty DeletedTaskFolders @()};$op.DeletedTaskFolders+=@($intent);$detail=[pscustomobject]@{ItemId=$Item.ItemId;Adapter='ScheduledTask';ManifestHash=$Operation.ManifestHash;Phase='TaskFolderDeleted';Intent=$intent};Add-WsmJournal $Paths $State 'TaskFolderDeleted' $Item.ItemId $detail};[void](Remove-WsmOwnedTaskFolders @($spec.Desired.FolderSecurity) $receipts @() $beforeDelete $afterDelete)}
    $record[0].Status='RolledBack';$State.PendingOperations=@($State.PendingOperations | Where-Object ItemId -CNE $Item.ItemId);Add-WsmJournal $Paths $State RollbackCompleted $Item.ItemId ([pscustomobject]@{Status='RolledBack';Absent=$true})
}
function Get-WsmRollbackPreview {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory)
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId;$s=Get-WsmOperationState $paths $p;if(@($s.PendingOperations | Where-Object {$_.Phase -in @('RollbackPrepared','RollbackAdapter')}).Count){throw 'Interrupted rollback requires RepairOperation before a new preview.'};if(@($s.PendingOperations | Where-Object Phase -EQ 'AdapterCreating').Count){throw 'Interrupted adapter creation requires RepairOperation before rollback preview.'};$rows=@(foreach($item in $p.Plan.Items){$r=@($s.Items | Where-Object ItemId -CEQ $item.ItemId);if($r.Count -and $r[0].CreatedByTool -and $r[0].Status -ne 'RolledBack'){$spec=$item.MigrationSpec;$hash='';$blocked=($spec.Adapter -eq 'WindowsFeature');$reason='';try{if($spec.Adapter -eq 'FileScope'){$hash=Get-WsmFileScopeDigest $spec.TargetPath $spec.Metadata}else{$hash=Get-WsmHashText ((Get-WsmAdapterState $spec) | ConvertTo-Json -Depth 15 -Compress);$receipts=@();if($spec.Adapter -eq 'ScheduledTask'){$receipts=Get-WsmTaskSecurityReceiptsForSpec $spec (Get-WsmTaskSecurityOwnershipReceipts $s)}elseif($r[0].PSObject.Properties['AuxiliaryOwnership']){$receipts=@($r[0].AuxiliaryOwnership)};$staged=Test-WsmAdapterConfiguration $spec Staged $receipts;$final=Test-WsmAdapterConfiguration $spec Final $receipts;if(-not $staged.Passed -and -not $final.Passed){$blocked=$true;$reason='Created object or owned task security drifted.'}}}catch{$blocked=$true;$reason='Created object verification failed: '+$_.Exception.GetType().FullName};[pscustomobject]@{ItemId=$item.ItemId;Adapter=$spec.Adapter;CurrentHash=$hash;Backup=$r[0].Backup;Action='RemoveCreatedOrRestorePreviousOwned';Blocked=$blocked;Reason=$reason}}})
    $preview=[pscustomobject]@{PairId=$s.PairId;ManifestHash=$ExpectedHash;DataReconcileRequired=($s.Cutover -and $s.Cutover.NewTransactionsPossible);Rows=$rows;SourceRestart='Never automatic';NetworkRollback='Reviewed domain/network procedure; never automatic source restart'}
    $preview | Add-Member NoteProperty PreviewHash (Get-WsmHashText ($preview | ConvertTo-Json -Depth 15 -Compress));$preview
}
function Invoke-WsmRollback {
    [CmdletBinding(SupportsShouldProcess)]param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[string]$PreviewHash,[string]$Acknowledgement)
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Manifest.Target.Fingerprint;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId
    Invoke-WsmLocked $paths.Root {$s=Get-WsmOperationState $paths $p;$preview=Get-WsmRollbackPreview $ManifestPath $ExpectedHash $StateDirectory;if($PreviewHash -ine $preview.PreviewHash -or $Acknowledgement -cne ('ROLLBACK '+$s.PairId)){throw 'Rollback preview changed or pair acknowledgement missing.'};if($preview.DataReconcileRequired -and -not (Test-WsmEvidence $s '' RollbackReconcile $ExpectedHash)){throw 'New target transactions may exist; stop writers and reconcile data before rollback.'};if(@($preview.Rows | Where-Object Blocked).Count){throw 'Dedicated feature rollback required.'};if(-not $PSCmdlet.ShouldProcess($s.PairId,'Rollback exactly reviewed created objects/owned roots; keep displaced content')){return $preview}
        $reverse=@(Get-WsmRestoreOrder @($p.Plan.Items | Where-Object Decision -EQ Include));[array]::Reverse($reverse)
        foreach($item in $reverse){$record=@($s.Items | Where-Object ItemId -CEQ $item.ItemId);if(-not $record.Count -or -not $record[0].CreatedByTool -or $record[0].Status -eq 'RolledBack'){continue};$spec=$item.MigrationSpec;Add-WsmJournal $paths $s 'RollbackStarted' $item.ItemId ([pscustomobject]@{Adapter=$spec.Adapter})
            if($spec.Adapter -eq 'FileScope'){
                $target=ConvertTo-WsmCanonicalPath $spec.TargetPath;$parent=[IO.Path]::GetDirectoryName($target);$backup=$record[0].Backup
                $op=[pscustomobject]@{ItemId=$item.ItemId;Phase='RollbackPrepared';ManifestHash=$ExpectedHash;Target=$target;Retained=(Join-Path $parent ('.wsm-rollback-retained-'+[Guid]::NewGuid().ToString('N')));CurrentHash=(Get-WsmFileScopeDigest $target $spec.Metadata);Backup=$backup;BackupHash=''}
                if($backup){$op.BackupHash=Get-WsmFileScopeDigest $backup $spec.Metadata;if(-not $op.BackupHash){throw 'Approved rollback backup missing.'}}
                $s.PendingOperations+=@($op);$s.Stage='RollbackRunning';Add-WsmJournal $paths $s RollbackIntent $item.ItemId $op
                Complete-WsmFileRollback $item $op $paths $s;continue
            }
            else{$op=[pscustomobject]@{ItemId=$item.ItemId;Phase='RollbackAdapter';ManifestHash=$ExpectedHash;Adapter=$spec.Adapter;SpecHash=(Get-WsmHashText ($spec | ConvertTo-Json -Depth 40 -Compress))};$s.PendingOperations+=@($op);$s.Stage='RollbackRunning';Add-WsmJournal $paths $s RollbackIntent $item.ItemId $op;Complete-WsmAdapterRollback $item $op $paths $s}
        };$s.Stage='RolledBack';Add-WsmJournal $paths $s 'RollbackFinished' '' ([pscustomobject]@{SourceRestarted=$false});$s
    }
}
